use crate::{StorageError, StorageResult};
use std::fs;
use std::path::{Component, Path, PathBuf};
use uuid::Uuid;

/// Minimal object-store contract. Keys are generated by AX Storage, never taken
/// directly from user-supplied filenames or paths.
pub trait ObjectStore: Send + Sync {
    fn put(&self, key: &str, bytes: &[u8]) -> StorageResult<()>;
    fn get(&self, key: &str) -> StorageResult<Vec<u8>>;
    fn delete_prefix(&self, prefix: &str) -> StorageResult<()>;
}

pub struct LocalFsObjectStore {
    root: PathBuf,
}

impl LocalFsObjectStore {
    pub fn new(root: impl Into<PathBuf>) -> StorageResult<Self> {
        let root = root.into();
        fs::create_dir_all(&root)?;
        let root = fs::canonicalize(root)?;
        Ok(Self { root })
    }

    fn resolve(&self, key: &str) -> StorageResult<PathBuf> {
        let path = Path::new(key);
        if path.as_os_str().is_empty()
            || path.components().any(|part| !matches!(part, Component::Normal(_)))
        {
            return Err(StorageError::InvalidConfiguration("unsafe object key"));
        }
        Ok(self.root.join(path))
    }
}

impl ObjectStore for LocalFsObjectStore {
    fn put(&self, key: &str, bytes: &[u8]) -> StorageResult<()> {
        let path = self.resolve(key)?;
        let parent = path.parent().ok_or(StorageError::InvalidConfiguration("key has no parent"))?;
        fs::create_dir_all(parent)?;
        let temporary = parent.join(format!(".{}.tmp", Uuid::new_v4()));
        fs::write(&temporary, bytes)?;
        if let Err(error) = fs::rename(&temporary, &path) {
            let _ = fs::remove_file(&temporary);
            return Err(StorageError::Io(error));
        }
        Ok(())
    }

    fn get(&self, key: &str) -> StorageResult<Vec<u8>> {
        let path = self.resolve(key)?;
        fs::read(path).map_err(|error| {
            if error.kind() == std::io::ErrorKind::NotFound {
                StorageError::NotFound
            } else {
                StorageError::Io(error)
            }
        })
    }

    fn delete_prefix(&self, prefix: &str) -> StorageResult<()> {
        let path = self.resolve(prefix)?;
        match fs::remove_dir_all(path) {
            Ok(()) => Ok(()),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(StorageError::Io(error)),
        }
    }
}
